                    "textDocument": { "uri": self.uri },
                    "range": {
                        "start": { "line": 0, "character": 0 },
                        "end": { "line": end_line, "character": 0 },
                    },
                    "context": { "diagnostics": [] },
                }),
            )?;

            let import_edits = actions
                .as_array()
