/// Where scanning stopped, and what it produced.
#[derive(Debug, Clone, PartialEq)]
pub struct ScanResult {
    /// Literal and interpolation parts, in order, with adjacent literals merged.
    pub parts: Vec<StringPart>,
    /// Offset at which scanning stopped, exclusive.
    pub end: usize,
}

/// Resolve the three escape sequences in raw source text.
///
/// Piton has exactly three: a doubled backslash, a backslash before a doubled
/// slash, and a backslash before a dollar-brace. A backslash before anything
/// else is just a backslash, so text that happens to contain one is not
/// rejected.
#[must_use]
pub fn resolve_escapes(text: &str) -> String {
    if !text.contains('\\') {
        return text.to_owned();
    }
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(at) = rest.find('\\') {
        out.push_str(&rest[..at]);
        let after = &rest[at + 1..];
        if let Some(tail) = after.strip_prefix('\\') {
            out.push('\\');
            rest = tail;
        } else if let Some(tail) = after.strip_prefix("//") {
            out.push_str("//");
            rest = tail;
        } else if let Some(tail) = after.strip_prefix("${") {
            out.push_str("${");
            rest = tail;
        } else {
            out.push('\\');
            rest = after;
        }
    }
    out.push_str(rest);
    out
}

