    parts.all(|tail| !tail.is_empty() && tail.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_'))
}
    fn add_str(&mut self, text: &str, from: usize, to: usize) {
        for ch in text.chars() {
            self.add(ch, from, to);
        }
