        let leading = out.chars().all(|c| c == '_');
        if c.is_alphanumeric() && c.len_utf16() == 1 || (c == ' ' && !leading) {
            out.push(c);
        } else {
            out.extend(std::iter::repeat_n('_', c.len_utf16()));
        }
        at += c.len_utf8();
    }
    out
}""")

